S("carriles", "RM-NEF-021", "Hiponatremia hipovolémica con sodio urinario mayor de 20 mEq/L: pérdida renal, como la diuresis osmótica",
  "Nefrología · hiponatremia hipovolémica",
  ("Hiponatremia hipovolémica", ["Pérdida de sodio y agua con reposición hipotónica.", "El sodio urinario localiza la pérdida."]),
  ("Pregunta de causa", ["¿Qué causa hiponatremia hipovolémica con sodio urinario mayor de 20 mEq/L?"]),
  ["Sodio urinario menor de 20 a 30 mEq/L: pérdida extrarrenal (vómitos, diarrea, quemaduras, tercer espacio como la pancreatitis aguda). Mayor de 20 a 30: pérdida renal.",
   "Causas renales: diuréticos (sobre todo tiazidas), diuresis osmótica por glucosa, manitol o cetonas, nefropatía perdedora de sal, pierde-sal cerebral y déficit de mineralocorticoides.",
   "Insuficiencia renal aguda o crónica: hiponatremia euvolémica o hipervolémica. Déficit de glucocorticoides: sobre todo euvolémica (exceso de ADH).",
   "Tratamiento: solución salina isotónica; no corregir el sodio más de 8 a 10 mmol/L en 24 horas (desmielinización osmótica); al reponer volumen cae la ADH y puede haber sobrecorrección."],
  "Spasovski et al., guía ESE/ESICM/ERBP de hiponatremia (Nephrol Dial Transplant 2014); Adrogué y Madias, N Engl J Med 2000; Harrison, 21.ª ed. (2022).",
  op=("¿Causa de hiponatremia hipovolémica?", ["Sí: la glucosa arrastra agua y sodio por el túbulo", "No: la hiponatremia suele ser euvolémica o hipervolémica", "No: la hiponatremia suele ser euvolémica o hipervolémica", "No: sobre todo euvolémica, por exceso de ADH", "No: tercer espacio con sodio urinario bajo"],
      {0: "Diuresis osmótica", 1: "Insuficiencia renal aguda", 2: "Insuficiencia renal crónica", 3: "Deficiencia de glucocorticoides", 4: "Pancreatitis aguda"}),
  d=dict(rotulo="Dónde ubicar cada causa según el sodio urinario", carriles=["Pérdida extrarrenal (Na urinario < 20)", "Pérdida renal (Na urinario > 20)", "No hipovolémicas"],
         pasos=[(0, "Pancreatitis aguda", "Secuestro en tercer espacio; Na urinario bajo", False),
                (0, "Vómitos, diarrea y quemaduras", "El riñón conserva el sodio", False),
                (1, "Diuresis osmótica", "Glucosa, manitol o cetonas arrastran agua y sodio", True),
                (1, "Diuréticos y déficit de aldosterona", "Pérdida renal de sodio", False),
                (2, "Insuficiencia renal aguda o crónica", "Euvolémica o hipervolémica", False),
                (2, "Déficit de glucocorticoides", "Sobre todo euvolémica, por exceso de ADH", False)],
         veredicto=("Hiponatremia hipovolémica con Na urinario alto = pérdida renal (diuresis osmótica)", "La pancreatitis aguda pierde sodio por el tercer espacio, con sodio urinario bajo.")),
  clasif=dict(titulo="Hiponatremia hipovolémica según el sodio urinario", cols=["Sodio urinario", "Origen", "Ejemplos"],
              filas=[["Menor de 20 a 30 mEq/L", "Extrarrenal", "Vómitos, diarrea, quemaduras, pancreatitis aguda"],
                     ["Mayor de 20 a 30 mEq/L", "Renal", "Diuréticos, diuresis osmótica, déficit mineralocorticoide"]],
              caso=1, ancho_primera=230,
              nota="El déficit de glucocorticoides (opción D) puede acompañarse de sodio urinario alto; la clave del banco se mantiene."))

# 022 · CHECKLIST · nefritis lúpica
S("checklist", "RM-NEF-022", "Mujer joven con citopenias, serositis, síndrome nefrótico y sedimento telescopado: nefropatía lúpica",
  "Nefrología · nefritis lúpica",
  ("Nefritis lúpica", ["Afecta a 40 a 60 % de los pacientes con lupus y es la principal causa de morbilidad.", "El sedimento telescopado reúne hematíes, leucocitos y cilindros de todos los tipos."]),
  ("Mujer de 28 años", ["Tres meses de astenia, vómitos y edema progresivo; anasarca y derrame pleural.", "PA 180/110; Hb 8, plaquetas 40 000, Cr 6, proteinuria 3,8 g/24 h."]),
  ["Anemia, plaquetopenia, serositis, hipertensión, síndrome nefrótico y deterioro renal en una mujer joven: lupus con nefritis hasta demostrar lo contrario.",
   "Diagnóstico: ANA, anti-ADN de doble cadena, C3 y C4 bajos, anti-Sm y, sobre todo, biopsia renal con clasificación ISN/RPS (clases I a VI; la IV difusa es la más grave y frecuente).",
   "Clases III y IV: glucocorticoides más micofenolato o ciclofosfamida; las guías recientes añaden belimumab o voclosporina. Hidroxicloroquina para todos; IECA o ARA-II para la proteinuria.",
   "La nefropatía diabética e hipertensiva evolucionan en años, sin plaquetopenia ni sedimento activo; la amiloidosis da síndrome nefrótico sin sedimento telescopado."],
  "KDIGO, manejo de la nefritis lúpica (2024); ACR, nefritis lúpica (Arthritis Rheumatol 2025).",
  op=("¿Diagnóstico más probable?", ["No: sin sedimento telescopado ni plaquetopenia", "No: evoluciona en años, sin sedimento activo", "No: evoluciona en años, sin plaquetopenia", "No: no explica citopenias ni serositis", "Sí: lupus con síndrome nefrítico y nefrótico mixto"],
      {}),
  d=dict(rotulo="Qué se hace ante la sospecha de nefritis lúpica", tag="DIAGNÓSTICO",
         pasos=[("Reconocer el lupus con nefritis", "Mujer joven, citopenias, serositis y sedimento telescopado", True),
                ("Anticuerpos y complemento", "ANA, anti-ADN de doble cadena, anti-Sm, C3 y C4", False),
                ("Biopsia renal", "Clasifica en ISN/RPS clases I a VI y guía la terapia", False),
                ("Tratar según la clase", "Clases III o IV: glucocorticoides más micofenolato o ciclofosfamida", False),
                ("Medidas para todos", "Hidroxicloroquina; IECA o ARA-II para la proteinuria", False)],
         no_hacer=[("Pensar en nefropatía diabética o hipertensiva", "Evolucionan en años, sin plaquetopenia ni sedimento activo"), ("Pensar en amiloidosis", "Da síndrome nefrótico sin sedimento telescopado")],
         no_titulo="Opciones que no explican el cuadro",
         veredicto=("Citopenias + serositis + sedimento telescopado = nefropatía lúpica", "La hipertensión y la diabetes no producen plaquetopenia ni sedimento activo.")),
  clasif=dict(titulo="Clasificación ISN/RPS de la nefritis lúpica", cols=["Clase", "Nombre"],
              filas=[["I", "Mesangial mínima"], ["II", "Proliferativa mesangial"], ["III", "Proliferativa focal"],
                     ["IV", "Proliferativa difusa (la más grave y frecuente)"], ["V", "Membranosa"], ["VI", "Esclerosis avanzada"]],
              caso=3, ancho_primera=80, nota="Las clases III y IV se tratan con glucocorticoides más micofenolato o ciclofosfamida."))
